/**
 * Protoboard Dark and Light for the terminal outside VS Code: a Ghostty theme
 * per scheme and herdr's `[theme]` tables, both read from the VS Code themes
 * (`colorTheme`) so the integrated terminal, Ghostty and herdr show the same
 * colours. `npm run themes` writes themes/ghostty/ and themes/herdr/ from here;
 * `npm run themes:install` puts them into this machine's configs. No VS Code API here.
 */
import { type ColorTheme, mixHex } from "./themeColors.js";

/** The generated files under themes/: Ghostty finds a theme by its file name. */
export const TERMINAL_FILES = { ghostty: { dark: "ghostty/Protoboard Dark", light: "ghostty/Protoboard Light" }, herdr: "herdr/theme.toml" } as const;

/** The value for Ghostty's `theme =`: follows the system's light or dark setting. */
export const GHOSTTY_THEME = "light:Protoboard Light,dark:Protoboard Dark";

const HEADER = "generated by `npm run themes` in protoboard-stack/packages/vscode-protoboard from the Protoboard VS Code themes; edit src/themeColors.ts there, not this file";

/** A #rrggbb[aa] colour laid over `under` as opaque #rrggbb (terminals take no alpha). */
export function flatten(color: string, under: string): string {
  if (color.length !== 9) return color;
  return mixHex(under, color.slice(0, 7), parseInt(color.slice(7), 16) / 255);
}

const ANSI = ["Black", "Red", "Green", "Yellow", "Blue", "Magenta", "Cyan", "White"];

/** A Ghostty theme file: the integrated terminal's palette, cursor and selection, and the panel border for splits. */
export function ghosttyTheme(theme: ColorTheme): string {
  const c = theme.colors;
  const bg = c["terminal.background"];
  const palette = [...ANSI.map((n) => c[`terminal.ansi${n}`]), ...ANSI.map((n) => c[`terminal.ansiBright${n}`])];
  return [
    `# ${theme.name}: ${HEADER}`,
    `background = ${bg}`,
    `foreground = ${c["terminal.foreground"]}`,
    ...palette.map((p, i) => `palette = ${i}=${p}`),
    `cursor-color = ${c["terminalCursor.foreground"]}`,
    `cursor-text = ${bg}`,
    `selection-background = ${flatten(c["terminal.selectionBackground"], bg)}`,
    `split-divider-color = ${c["panel.border"]}`,
    "",
  ].join("\n");
}

/** herdr's colour tokens for one scheme, each from the VS Code colour that plays the same part. */
export function herdrColors(theme: ColorTheme): Record<string, string> {
  const c = theme.colors;
  const bg = c["terminal.background"];
  const side = c["editor.background"];
  return {
    panel_bg: bg,
    sidebar_bg: side,
    active_row_bg: c["list.activeSelectionBackground"],
    selection_bg: flatten(c["terminal.selectionBackground"], side),
    surface0: c["panel.border"],
    surface1: c["list.activeSelectionBackground"],
    surface_dim: c["list.hoverBackground"],
    overlay0: flatten(c["disabledForeground"], bg),
    overlay1: c["descriptionForeground"],
    subtext0: mixHex(c["descriptionForeground"], c["terminal.foreground"], 0.5),
    text: c["terminal.foreground"],
    accent: c["textLink.foreground"],
    peach: c["textLink.foreground"],
    red: c["terminal.ansiRed"],
    green: c["terminal.ansiGreen"],
    yellow: c["terminal.ansiYellow"],
    blue: c["terminal.ansiBlue"],
    teal: c["terminal.ansiCyan"],
    mauve: c["terminal.ansiMagenta"],
  };
}

/** herdr's `[theme]` tables: the host terminal's palette (Ghostty's Protoboard theme) under Protoboard's UI colours, switching with the system. */
export function herdrTheme(dark: ColorTheme, light: ColorTheme): string {
  const table = (name: string, t: ColorTheme) => [`[theme.custom.${name}]`, ...Object.entries(herdrColors(t)).map(([k, v]) => `${k} = "${v}"`)].join("\n");
  return [`# Protoboard Dark and Light: ${HEADER}`, "[theme]", 'name = "terminal"', "auto_switch = true", 'dark_name = "terminal"', 'light_name = "terminal"', "", table("dark", dark), "", table("light", light), ""].join("\n");
}

/** A Ghostty config with its `theme =` line set to Protoboard's (added when it has none). */
export function withGhosttyTheme(config: string): string {
  const line = `theme = ${GHOSTTY_THEME}`;
  if (/^\s*theme\s*=.*$/m.test(config)) return config.replace(/^\s*theme\s*=.*$/m, line);
  return `${config}${config && !config.endsWith("\n") ? "\n" : ""}${line}\n`;
}

/** A herdr config.toml with its `[theme]` tables (and the comments right above them) replaced by `block`; the rest is kept as it was. */
export function withHerdrTheme(config: string, block: string): string {
  const note = (line: string) => /^\s*(#.*)?$/.test(line);
  const kept: string[] = [];
  // comments at the end of a theme table: they may head the table after it
  let tail: string[] = [];
  let inTheme = false;
  for (const line of config.split("\n")) {
    const table = line.match(/^\s*\[([^\]]+)\]/);
    if (table) {
      const theme = table[1].trim() === "theme" || table[1].trim().startsWith("theme.");
      if (theme) while (kept.length && note(kept[kept.length - 1])) kept.pop();
      else if (inTheme) kept.push(...tail);
      inTheme = theme;
      tail = [];
    }
    if (!inTheme) kept.push(line);
    else tail = note(line) ? [...tail, line] : [];
  }
  const rest = kept.join("\n").trimEnd();
  return `${rest ? `${rest}\n\n` : ""}${block}`;
}
